<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { api,ApiError,errorText } from '../api'
import { date,listItems } from '../domain'
import type { Row } from '../domain'
import { useAuth } from '../stores/auth'
import PageState from '../components/PageState.vue'
import { Search,Download,ScrollText,ArrowUpRight } from 'lucide-vue-next'
const auth=useAuth(),items=ref<Row[]>([]),actions=ref<Row[]>([]),total=ref(0),page=ref(1),loading=ref(false),error=ref(''),operationError=ref(''),keyword=ref(''),action=ref(''),range=ref<string[]>([]),format=ref('xlsx'),busy=ref(false),selected=ref<Row|null>(null),detailOpen=ref(false),verifyOpen=ref(false),code=ref(''),verifyError=ref('')
let sequence=0
const filters=ref<Record<string,unknown>>({})
async function load(){const n=++sequence;loading.value=true;error.value='';try{const data=await api.get('/audit',{...filters.value,page:page.value,pageSize:20});if(n!==sequence)return;items.value=listItems(data);total.value=data.total??items.value.length;actions.value=data.actions??[]}catch(e){if(n===sequence)error.value=errorText(e)}finally{if(n===sequence)loading.value=false}}
function search(){filters.value={keyword:keyword.value.trim()||undefined,action:action.value||undefined,from:range.value?.[0],to:range.value?.[1]};page.value=1;load()}
function reset(){keyword.value='';action.value='';range.value=[];search()}
function details(row:Row){selected.value=row;detailOpen.value=true}
async function download(){busy.value=true;operationError.value='';try{const params=new URLSearchParams({format:format.value});for(const [k,v] of Object.entries(filters.value))if(v!=null)params.set(k,String(v));await api.download('/audit/export?'+params,`操作日志.${format.value}`);verifyOpen.value=false}catch(e){if(e instanceof ApiError&&e.code==='FRESH_TOTP_REQUIRED'){verifyOpen.value=true;verifyError.value=''}else operationError.value=errorText(e)}finally{busy.value=false}}
async function verify(){if(!/^\d{6}$/.test(code.value)){verifyError.value='请输入六位动态验证码';return}busy.value=true;verifyError.value='';try{await api.post('/auth/totp/verify',{code:code.value});code.value='';await download()}catch(e){verifyError.value=errorText(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template>
<section class="page-heading"><div><p class="eyebrow">ACTIVITY & AUDIT</p><h1>操作日志</h1><p class="muted">查找组织变更和任务操作，按追踪号核对办理记录。</p></div><div class="action-strip"><el-select v-model="format" aria-label="日志导出格式" style="width:110px"><el-option label="Excel" value="xlsx"/><el-option label="CSV" value="csv"/></el-select><el-button :loading="busy" :disabled="loading||!!error" @click="download"><Download :size="15"/>导出筛选结果</el-button></div></section>
<el-alert v-if="operationError" :title="operationError" type="error" :closable="false"/>
<section class="panel records-panel">
 <form class="records-toolbar" @submit.prevent="search"><el-input v-model="keyword" clearable placeholder="搜索人员、公司、动作编码或追踪号" aria-label="日志关键词"><template #prefix><Search :size="16"/></template></el-input><el-select v-model="action" filterable clearable placeholder="全部操作" aria-label="日志操作类型"><el-option v-for="a in actions" :key="a.value" :label="a.label" :value="a.value"/></el-select><el-date-picker v-model="range" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" aria-label="日志日期范围"/><div class="action-strip"><el-button native-type="submit" type="primary">查询</el-button><el-button @click="reset">重置</el-button></div></form>
 <div class="records-caption"><span><ScrollText :size="14"/> {{ total }} 条记录</span><span>{{ auth.me?.companyName||'全局授权范围' }} · 导出最多 5000 条</span></div>
 <PageState :loading="loading" :error="error" :empty="!items.length" @retry="load">
 <div class="audit-list"><button v-for="r in items" :key="r.id" class="audit-row" @click="details(r)"><span class="audit-avatar">{{ (r.actorName||'人').slice(0,1) }}</span><span class="audit-content"><strong>{{ r.actionLabel||r.action }}</strong><span>{{ r.actorName||'人员 #'+r.actorId }}<i>·</i>{{ r.companyName||'公司 #'+r.companyId }}<i>·</i>{{ r.objectType||'对象' }} {{ r.objectId?'#'+r.objectId:'汇总数据' }}</span><small>{{ r.traceId }}</small></span><span class="audit-end"><time>{{ date(r.createdAt) }}</time><span v-if="r.delegationId" class="status">代理办理</span><ArrowUpRight :size="15"/></span></button></div>
 </PageState>
 <div class="pagination"><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="load"/></div>
</section>
<el-dialog v-model="detailOpen" title="操作记录详情" align-center class="app-card-dialog" width="640px"><template v-if="selected"><div class="record-detail-title"><span class="status">已记录</span><h2>{{ selected.actionLabel||selected.action }}</h2><p class="muted">{{ date(selected.createdAt) }}</p></div><dl class="record-details"><dt>操作人</dt><dd>{{ selected.actorName }} <small>#{{ selected.actorId }}</small></dd><dt>所属公司</dt><dd>{{ selected.companyName }} <small>#{{ selected.companyId }}</small></dd><dt>操作对象</dt><dd>{{ selected.objectType }} · {{ selected.objectId?'#'+selected.objectId:'汇总数据' }}</dd><dt>动作编码</dt><dd><code>{{ selected.action }}</code></dd><dt>追踪号</dt><dd><code>{{ selected.traceId }}</code></dd><dt>代理授权</dt><dd>{{ selected.delegationId?'#'+selected.delegationId:'本人岗位办理' }}</dd><dt>日志编号</dt><dd>#{{ selected.id }}</dd></dl><p class="scope-note">人员和公司显示当前名称。历史日志未记录的修改前后值不予补写。</p></template><template #footer><el-button @click="detailOpen=false">关闭</el-button></template></el-dialog>
<el-dialog v-model="verifyOpen" title="验证后导出日志" align-center class="app-card-dialog" width="420px" @closed="code='';verifyError=''"><p class="muted">请输入验证器中的动态验证码，验证后继续导出当前筛选结果。</p><el-input v-model="code" maxlength="6" inputmode="numeric" autocomplete="one-time-code" aria-label="日志导出动态验证码" @keyup.enter="verify"/><el-alert v-if="verifyError" :title="verifyError" type="error" :closable="false"/><template #footer><el-button @click="verifyOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="verify">验证并导出</el-button></template></el-dialog>
</template>
<style scoped>
.records-panel{padding:0}.records-toolbar{padding:20px}.records-caption{padding:12px 20px;border-block:1px solid var(--line);background:var(--surface-muted)}.records-caption,.records-caption>span{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:12px;color:var(--muted)}.audit-row{display:flex;align-items:center;gap:14px;width:100%;padding:18px 22px;text-align:left;background:transparent;border:0;border-bottom:1px solid var(--line);color:var(--text);cursor:pointer;font:inherit}.audit-row:hover{background:var(--surface-hover)}.audit-row:focus-visible{outline:2px solid var(--brand);outline-offset:-3px}.audit-avatar{display:grid;place-items:center;width:34px;height:34px;flex-shrink:0;border:1px solid var(--line);border-radius:50%;background:var(--surface-muted);font-size:12px}.audit-content{display:flex;flex:1;min-width:0;flex-direction:column;gap:5px}.audit-content strong{font-size:14px;font-weight:600}.audit-content>span,.audit-content small{color:var(--muted);font-size:12px;overflow-wrap:anywhere}.audit-content i{font-style:normal;padding:0 7px}.audit-content small{font-family:ui-monospace,monospace;font-size:11px}.audit-end{display:flex;align-items:center;gap:12px;color:var(--muted);font-size:12px}.record-detail-title{padding-bottom:16px;border-bottom:1px solid var(--line)}.record-details{display:grid;grid-template-columns:90px minmax(0,1fr);gap:16px;font-size:13px}.record-details dt{color:var(--muted)}.record-details dd{margin:0;overflow-wrap:anywhere}.record-details small{color:var(--muted)}code{font-size:12px}.pagination{padding:8px 20px}@media(max-width:768px){.audit-end{align-items:flex-end;flex-direction:column;gap:8px}.audit-row{padding:16px;align-items:flex-start}.audit-avatar{display:none}.records-caption{align-items:flex-start;flex-direction:column}.audit-end time{max-width:90px;text-align:right}.record-details{grid-template-columns:76px minmax(0,1fr)}}
</style>
